[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellStream Platform — Integrated Energy Data Management</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<script src="https://cdn.tailwindcss.com"></script>
<script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
<style>
  :root {
    --bg-primary: #0D1B2A;
    --bg-secondary: #111F30;
    --bg-card: #152034;
    --bg-card-hover: #1A2A40;
    --accent: #00B4D8;
    --accent-glow: rgba(0,180,216,0.15);
    --accent-secondary: #0077B6;
    --accent-green: #6CC24A;
    --accent-green-glow: rgba(108,194,74,0.15);
    --text-primary: #E8EDF2;
    --text-secondary: #94A3B8;
    --text-muted: #64748B;
    --border: #1E3048;
    --border-light: #263548;
    --radius: 0.75rem;
    --radius-sm: 0.5rem;
    --radius-lg: 1rem;
    --shadow-card: 0 1px 3px rgba(0,0,0,0.3), 0 1px 2px rgba(0,0,0,0.2);
    --shadow-lg: 0 10px 40px rgba(0,0,0,0.4);
    --transition: 200ms cubic-bezier(0.4,0,0.2,1);
  }
  * { margin:0; padding:0; box-sizing:border-box; }
  html { scroll-behavior:smooth; }
  body {
    font-family: 'Inter', system-ui, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
  }

  /* Navigation */
  .nav { position:fixed; top:0; left:0; right:0; z-index:100; background:rgba(13,27,42,0.92); backdrop-filter:blur(20px); border-bottom:1px solid var(--border); transition:background var(--transition); }
  .nav-container { max-width:1280px; margin:0 auto; padding:0 1.5rem; display:flex; align-items:center; justify-content:space-between; height:4rem; }
  .nav-logo { display:flex; align-items:center; gap:0.625rem; font-weight:700; font-size:1.25rem; color:var(--text-primary); text-decoration:none; }
  .nav-logo svg { width:32px; height:32px; }
  .nav-links { display:flex; align-items:center; gap:0.25rem; }
  .nav-dropdown { position:relative; }
  .nav-dropdown-btn { display:flex; align-items:center; gap:0.25rem; padding:0.5rem 0.75rem; color:var(--text-secondary); font-size:0.875rem; font-weight:500; background:none; border:none; cursor:pointer; border-radius:var(--radius-sm); transition:all var(--transition); font-family:inherit; }
  .nav-dropdown-btn:hover { color:var(--text-primary); background:rgba(255,255,255,0.05); }
  .nav-dropdown-btn svg { width:14px; height:14px; transition:transform var(--transition); }
  .nav-dropdown.open .nav-dropdown-btn svg { transform:rotate(180deg); }
  .nav-dropdown-menu { position:absolute; top:calc(100% + 0.5rem); left:0; min-width:200px; background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius); padding:0.5rem; opacity:0; visibility:hidden; transform:translateY(-4px); transition:all var(--transition); box-shadow:var(--shadow-lg); }
  .nav-dropdown.open .nav-dropdown-menu { opacity:1; visibility:visible; transform:translateY(0); }
  .nav-dropdown-menu a { display:block; padding:0.625rem 0.75rem; color:var(--text-secondary); text-decoration:none; font-size:0.875rem; border-radius:var(--radius-sm); transition:all var(--transition); }
  .nav-dropdown-menu a:hover { color:var(--text-primary); background:rgba(255,255,255,0.05); }
  .nav-cta { display:inline-flex; align-items:center; gap:0.375rem; padding:0.5rem 1.25rem; background:var(--accent); color:#fff; font-size:0.875rem; font-weight:600; border-radius:var(--radius-sm); text-decoration:none; transition:all var(--transition); border:none; cursor:pointer; font-family:inherit; }
  .nav-cta:hover { background:#00C8F0; box-shadow:0 0 20px var(--accent-glow); transform:translateY(-1px); }
  .nav-mobile-toggle { display:none; background:none; border:none; color:var(--text-primary); cursor:pointer; padding:0.5rem; }
  .mobile-menu { display:none; position:fixed; top:4rem; left:0; right:0; bottom:0; background:var(--bg-primary); z-index:99; padding:1.5rem; overflow-y:auto; }
  .mobile-menu.active { display:block; }
  .mobile-menu a, .mobile-menu button { display:flex; align-items:center; justify-content:space-between; width:100%; padding:0.75rem 0; color:var(--text-secondary); text-decoration:none; font-size:1rem; border:none; background:none; cursor:pointer; border-bottom:1px solid var(--border); font-family:inherit; }
  .mobile-menu .mobile-sub { padding-left:1.5rem; font-size:0.9375rem; }
  .mobile-menu .mobile-cta { margin-top:1rem; justify-content:center; background:var(--accent); color:#fff; border-radius:var(--radius-sm); border:none; font-weight:600; padding:0.875rem; }

  /* Sections */
  .section { padding:5rem 1.5rem; }
  .section-label { font-size:0.75rem; font-weight:700; letter-spacing:0.15em; color:var(--accent); text-transform:uppercase; margin-bottom:0.75rem; }
  .section-heading { font-size:clamp(1.75rem, 4vw, 2.75rem); font-weight:700; line-height:1.15; margin-bottom:1rem; }
  .section-subtitle { font-size:1.125rem; color:var(--text-secondary); max-width:640px; line-height:1.7; }
  .container { max-width:1280px; margin:0 auto; }

  /* Hero */
  .hero { padding:8rem 1.5rem 5rem; position:relative; overflow:hidden; }
  .hero::before { content:''; position:absolute; top:-50%; right:-20%; width:600px; height:600px; background:radial-gradient(circle, var(--accent-glow), transparent 70%); pointer-events:none; }
  .hero::after { content:''; position:absolute; bottom:-30%; left:-10%; width:400px; height:400px; background:radial-gradient(circle, rgba(0,119,182,0.08), transparent 70%); pointer-events:none; }
  .hero-title { font-size:clamp(2rem, 5vw, 3.5rem); font-weight:800; line-height:1.08; margin-bottom:1.5rem; max-width:800px; position:relative; z-index:1; }
  .hero-title span { color:var(--accent); }
  .hero-subtitle { font-size:1.125rem; color:var(--text-secondary); max-width:560px; margin-bottom:2.5rem; line-height:1.7; position:relative; z-index:1; }
  .hero-actions { display:flex; flex-wrap:wrap; gap:0.875rem; position:relative; z-index:1; }
  .btn-primary { display:inline-flex; align-items:center; gap:0.5rem; padding:0.875rem 2rem; background:var(--accent); color:#fff; font-size:0.9375rem; font-weight:600; border-radius:var(--radius-sm); text-decoration:none; transition:all var(--transition); border:none; cursor:pointer; font-family:inherit; }
  .btn-primary:hover { background:#00C8F0; box-shadow:0 0 30px var(--accent-glow); transform:translateY(-1px); }
  .btn-outline { display:inline-flex; align-items:center; gap:0.5rem; padding:0.875rem 2rem; background:transparent; color:var(--text-primary); font-size:0.9375rem; font-weight:600; border-radius:var(--radius-sm); text-decoration:none; border:1px solid var(--border-light); transition:all var(--transition); cursor:pointer; font-family:inherit; }
  .btn-outline:hover { border-color:var(--accent); background:rgba(0,180,216,0.05); }

  /* Cards */
  .card { background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius); transition:all var(--transition); }
  .card:hover { background:var(--bg-card-hover); border-color:var(--border-light); transform:translateY(-2px); box-shadow:var(--shadow-lg); }

  /* Industry Tabs */
  .tabs-nav { display:flex; flex-wrap:wrap; gap:0.5rem; margin-bottom:2rem; }
  .tab-btn { padding:0.625rem 1.25rem; background:transparent; color:var(--text-secondary); font-size:0.875rem; font-weight:500; border:1px solid var(--border); border-radius:2rem; cursor:pointer; transition:all var(--transition); font-family:inherit; }
  .tab-btn:hover { color:var(--text-primary); border-color:var(--border-light); }
  .tab-btn.active { background:var(--accent); color:#fff; border-color:var(--accent); }

  /* Feature Banner */
  .feature-banner { background:linear-gradient(135deg, #0A1628 0%, #152034 50%, #0D2137 100%); border:1px solid var(--border); border-radius:var(--radius-lg); padding:2.5rem; position:relative; overflow:hidden; }
  .feature-banner::before { content:''; position:absolute; top:0; right:0; width:300px; height:100%; background:linear-gradient(270deg, var(--accent-glow), transparent); pointer-events:none; }
  .feature-banner-tag { display:inline-block; padding:0.25rem 0.75rem; background:rgba(108,194,74,0.15); color:var(--accent-green); font-size:0.75rem; font-weight:600; border-radius:2rem; margin-bottom:0.75rem; }
  .feature-banner h3 { font-size:1.5rem; font-weight:700; margin-bottom:0.5rem; }

  /* Use Case Grid */
  .use-case-grid { display:grid; grid-template-columns:repeat(auto-fill, minmax(340px, 1fr)); gap:1rem; }
  .use-case-card { padding:1.75rem; cursor:pointer; }
  .use-case-card .icon-box { width:44px; height:44px; display:flex; align-items:center; justify-content:center; background:rgba(0,180,216,0.1); border-radius:var(--radius-sm); margin-bottom:1rem; color:var(--accent); }
  .use-case-card h4 { font-size:1.0625rem; font-weight:600; margin-bottom:0.5rem; }
  .use-case-card p { font-size:0.875rem; color:var(--text-muted); line-height:1.6; }

  /* Platform Diagram */
  .platform-diagram { display:flex; gap:2rem; justify-content:center; flex-wrap:wrap; padding:2rem 0; position:relative; }
  .platform-pillar { flex:1; min-width:280px; max-width:380px; padding:2.5rem 2rem; text-align:center; background:var(--bg-card); border:1px solid var(--border); border-radius:var(--radius-lg); position:relative; z-index:1; transition:all var(--transition); }
  .platform-pillar:hover { border-color:var(--accent); transform:translateY(-4px); box-shadow:0 20px 50px rgba(0,0,0,0.3); }
  .platform-pillar .pillar-icon { width:56px; height:56px; margin:0 auto 1.25rem; display:flex; align-items:center; justify-content:center; background:rgba(0,180,216,0.1); border-radius:50%; color:var(--accent); }
  .platform-pillar h4 { font-size:1.125rem; font-weight:600; margin-bottom:0.5rem; }
  .platform-pillar p { font-size:0.875rem; color:var(--text-muted); line-height:1.6; }
  .platform-connector { display:flex; align-items:center; justify-content:center; color:var(--accent); font-size:1.5rem; }
  @media (max-width:960px) { .platform-connector { transform:rotate(90deg); } }

  /* Culture & Renewables */
  .split-section { display:grid; grid-template-columns:1fr 1fr; gap:2rem; }
  @media (max-width:768px) { .split-section { grid-template-columns:1fr; } }

  /* Footer */
  .footer { background:var(--bg-secondary); border-top:1px solid var(--border); padding:4rem 1.5rem 2rem; }
  .footer-grid { display:grid; grid-template-columns:repeat(auto-fit, minmax(180px, 1fr)); gap:2rem; }
  .footer-col h5 { font-size:0.8125rem; font-weight:700; letter-spacing:0.08em; text-transform:uppercase; margin-bottom:1.25rem; color:var(--text-primary); }
  .footer-col a { display:block; color:var(--text-muted); text-decoration:none; font-size:0.875rem; margin-bottom:0.625rem; transition:color var(--transition); }
  .footer-col a:hover { color:var(--text-primary); }
  .footer-bottom { margin-top:3rem; padding-top:1.5rem; border-top:1px solid var(--border); display:flex; flex-wrap:wrap; justify-content:space-between; gap:1rem; font-size:0.8125rem; color:var(--text-muted); }

  /* Cookie Banner */
  .cookie-banner { position:fixed; bottom:0; left:0; right:0; z-index:200; background:var(--bg-card); border-top:1px solid var(--border); padding:1.25rem 1.5rem; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:1rem; box-shadow:0 -4px 20px rgba(0,0,0,0.3); transition:transform 300ms ease-out, opacity 300ms ease-out; }
  .cookie-banner.hidden { transform:translateY(100%); opacity:0; pointer-events:none; }
  .cookie-banner p { font-size:0.875rem; color:var(--text-secondary); max-width:680px; }
  .cookie-banner a { color:var(--accent); text-decoration:underline; }
  .cookie-actions { display:flex; gap:0.625rem; }
  .btn-sm { padding:0.5rem 1rem; font-size:0.8125rem; font-weight:600; border-radius:var(--radius-sm); cursor:pointer; transition:all var(--transition); font-family:inherit; }
  .btn-sm-primary { background:var(--accent); color:#fff; border:none; }
  .btn-sm-primary:hover { background:#00C8F0; }
  .btn-sm-ghost { background:transparent; color:var(--text-secondary); border:1px solid var(--border-light); }
  .btn-sm-ghost:hover { color:var(--text-primary); border-color:var(--text-muted); }

  /* Responsive */
  @media (max-width:768px) {
    .nav-links { display:none; }
    .nav-mobile-toggle { display:block; }
    .hero { padding:6rem 1.5rem 3rem; }
    .section { padding:3rem 1.5rem; }
    .use-case-grid { grid-template-columns:1fr; }
    .footer-grid { grid-template-columns:1fr 1fr; }
  }

  /* Animations */
  @keyframes fadeInUp { from { opacity:0; transform:translateY(20px); } to { opacity:1; transform:translateY(0); } }
  @keyframes fadeIn { from { opacity:0; } to { opacity:1; } }
  .animate-in { animation:fadeInUp 500ms ease-out forwards; }
  .delay-1 { animation-delay:100ms; }
  .delay-2 { animation-delay:200ms; }
  .delay-3 { animation-delay:300ms; }
</style>
</head>
<body>

<!-- Navigation -->
<nav class="nav" id="navbar">
  <div class="nav-container">
    <a href="index.html" class="nav-logo">
      <svg viewBox="0 0 32 32" fill="none"><rect width="32" height="32" rx="8" fill="#00B4D8"/><path d="M8 22V10l4 6 4-6v12M20 10v12M26 10l-4 6 4 6" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
      WellStream
    </a>
    <div class="nav-links" id="navLinks">
