        <button class="nav-dropdown-btn" onclick="toggleDropdown('platformDropdown')">Platform <svg><polyline points="6 9 12 15 18 9"/></svg></button>
        <div class="nav-dropdown-menu">
          <a href="platform-overview.html">Platform Overview</a>
          <a href="security.html">Security</a>
          <a href="integration.html">Integration</a>
        </div>
      </div>
      <div class="nav-dropdown" id="solutionsDropdown">
        <button class="nav-dropdown-btn" onclick="toggleDropdown('solutionsDropdown')">Solutions <svg><polyline points="6 9 12 15 18 9"/></svg></button>
