        <button class="nav-dropdown-btn" onclick="toggleDropdown('companyDropdown')">Company <svg><polyline points="6 9 12 15 18 9"/></svg></button>
        <div class="nav-dropdown-menu">
          <a href="index.html#culture">About Us</a>
          <a href="index.html#culture">Careers</a>
          <a href="request-demo.html">Contact</a>
