    <button class="nav-mobile-toggle" onclick="toggleMobileMenu()" aria-label="Menu">
      <i data-lucide="menu" id="menuIcon"></i>
    </button>
  </div>
</nav>

<!-- Mobile Menu -->
<div class="mobile-menu" id="mobileMenu">
  <button onclick="toggleMobileSub('mobilePlatform')">Platform <i data-lucide="chevron-down" style="width:18px;height:18px"></i></button>
  <div id="mobilePlatform" style="display:none">
    <a href="platform-overview.html" class="mobile-sub">Platform Overview</a>
    <a href="security.html" class="mobile-sub">Security</a>
    <a href="integration.html" class="mobile-sub">Integration</a>
  </div>
  <a href="index.html#use-cases">Solutions</a>
  <a href="index.html#culture">Company</a>
  <a href="request-demo.html" class="mobile-cta">Request A Demo</a>
</div>

<!-- Hero -->
<section class="hero">
  <div class="container">
    <h1 class="hero-title animate-in">GET REAL-TIME DATA <span>ACROSS YOUR ENTIRE OPERATION</span></h1>
    <p class="hero-subtitle animate-in delay-1">The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.</p>
    <div class="hero-actions animate-in delay-2">
      <a href="platform-overview.html" class="btn-primary"><i data-lucide="play-circle" style="width:18px;height:18px"></i> Explore the Platform</a>
      <a href="request-demo.html" class="btn-outline"><i data-lucide="calendar" style="width:18px;height:18px"></i> Request A Demo</a>
    </div>
  </div>
</section>

<!-- Featured Product Banner -->
<section class="section" style="padding-top:0">
  <div class="container">
    <div class="feature-banner animate-in">
      <div style="position:relative;z-index:1">
        <span class="feature-banner-tag">New</span>
        <h3>WellStream Innova</h3>
        <p style="color:var(--text-secondary);margin-bottom:1.25rem;max-width:500px">Real-Time Directional Data Exchange — monitor and adjust drilling trajectories with live data feeds from the rig floor to the operations center.</p>
        <a href="platform-overview.html" class="btn-outline" style="font-size:0.875rem;padding:0.625rem 1.5rem">Learn More <i data-lucide="arrow-right" style="width:14px;height:14px"></i></a>
      </div>
    </div>
  </div>
</section>

<!-- Use Cases -->
<section class="section" id="use-cases" style="padding-top:2rem">
  <div class="container">
    <span class="section-label">USE CASES</span>
    <h2 class="section-heading">See the WellStream Platform in Action</h2>
    <p class="section-subtitle" style="margin-bottom:3rem">From drilling to production, land to water, watch how WellStream transforms every phase of your operations. Streamline workflows, unlock real-time insights, and make every decision count with seamless, end-to-end data integration.</p>

    <!-- Industry Tabs -->
    <div class="tabs-nav" id="industryTabs">
      <button class="tab-btn active" data-tab="ep">E&P</button>
      <button class="tab-btn" data-tab="midstream">Midstream</button>
      <button class="tab-btn" data-tab="downstream">Downstream</button>
      <button class="tab-btn" data-tab="utilities">Utilities</button>
      <button class="tab-btn" data-tab="solar">Solar / Wind</button>
      <button class="tab-btn" data-tab="mining">Mining</button>
    </div>
    <div id="industryContent">
      <div class="use-case-grid" data-industry="ep">
        <div class="card use-case-card">
          <div class="icon-box"><i data-lucide="drill" style="width:22px;height:22px"></i></div>
          <h4>Drilling & Completions Management</h4>
          <p>Centralize drilling programs, daily reports, and well design data in one accessible hub.</p>
        </div>
        <div class="card use-case-card">
          <div class="icon-box"><i data-lucide="bar-chart-3" style="width:22px;height:22px"></i></div>
          <h4>Production Operations Oversight</h4>
          <p>Monitor production volumes, allocations, and decline curves with real-time dashboards.</p>
        </div>
        <div class="card use-case-card">
          <div class="icon-box"><i data-lucide="shield-check" style="width:22px;height:22px"></i></div>
          <h4>Asset Integrity Monitoring</h4>
          <p>Track well integrity risks, inspection schedules, and compliance status across your portfolio.</p>
        </div>
        <div class="card use-case-card">
          <div class="icon-box"><i data-lucide="droplets" style="width:22px;height:22px"></i></div>
          <h4>Hydraulic Frac Data Centralization</h4>
          <p>Consolidate frac stage data, chemical usage, and pressure readings for every completion.</p>
        </div>
        <div class="card use-case-card">
          <div class="icon-box"><i data-lucide="building-2" style="width:22px;height:22px"></i></div>
          <h4>Facility Construction & Commissioning</h4>
          <p>Manage site activity, construction milestones, and commissioning workflows digitally.</p>
        </div>
        <div class="card use-case-card">
          <div class="icon-box"><i data-lucide="map" style="width:22px;height:22px"></i></div>
          <h4>Geospatial Asset Analysis</h4>
          <p>Visualize well locations, land positions, and infrastructure on interactive map layers.</p>
        </div>
      </div>
    </div>
    <div style="margin-top:2rem;text-align:center">
      <a href="platform-overview.html" class="btn-outline">More Use Cases <i data-lucide="arrow-right" style="width:16px;height:16px"></i></a>
    </div>
  </div>
</section>

<!-- Platform Overview Diagram -->
<section class="section">
  <div class="container">
    <span class="section-label">THE PLATFORM</span>
    <h2 class="section-heading" style="text-align:center">Three Pillars, One Integrated System</h2>
    <p class="section-subtitle" style="text-align:center;margin:0 auto 3rem">From well data to production to land management — WellStream connects every layer of your energy operations.</p>
    <div class="platform-diagram">
      <div class="platform-pillar">
        <div class="pillar-icon"><i data-lucide="database" style="width:28px;height:28px"></i></div>
        <h4>Well Data Lifecycle</h4>
        <p>Plan, drill, complete, and manage wells from spud to abandonment with unified data capture and reporting.</p>
      </div>
      <div class="platform-connector">⟷</div>
      <div class="platform-pillar">
        <div class="pillar-icon"><i data-lucide="trending-up" style="width:28px;height:28px"></i></div>
        <h4>Production Data Lifecycle</h4>
        <p>Capture, allocate, report, and optimize production volumes with real-time dashboards and analytics.</p>
      </div>
      <div class="platform-connector">⟷</div>
      <div class="platform-pillar">
        <div class="pillar-icon"><i data-lucide="globe" style="width:28px;height:28px"></i></div>
        <h4>Land Data Management</h4>
        <p>Track leases, agreements, obligations, and mineral rights across your entire asset portfolio.</p>
      </div>
    </div>
  </div>
</section>

<!-- Company Culture -->
<section class="section" id="culture" style="background:var(--bg-secondary)">
  <div class="container">
    <div class="split-section" style="align-items:center">
      <div>
        <span class="section-label">OUR CULTURE</span>
        <h2 class="section-heading">WellStream: Fearless Innovation</h2>
