  // Accordion
  function toggleAccordion(header) {
    const item = header.parentElement;
    const body = item.querySelector('.accordion-body');
    const isActive = item.classList.contains('active');
    if (isActive) {
      item.classList.remove('active');
      body.style.maxHeight = '0';
    } else {
      item.classList.add('active');
      body.style.maxHeight = body.scrollHeight + 'px';
    }
  }

  // Carousel
  let currentSlide = 0;
  const track = document.getElementById('carouselTrack');
  const dots = document.querySelectorAll('#carouselDots .carousel-dot');
  function goToSlide(index) {
    currentSlide = index;
    track.style.transform = `translateX(-${index * 100}%)`;
    dots.forEach((d,i) => d.classList.toggle('active', i === index));
  }
  dots.forEach(dot => dot.addEventListener('click', () => goToSlide(parseInt(dot.dataset.index))));

  // Progress bars animation
  const progressObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const fill = entry.target;
        fill.style.width = fill.dataset.width + '%';
        progressObserver.unobserve(fill);
      }
    });
  }, { threshold: 0.5 });
  document.querySelectorAll('.progress-fill').forEach(f => progressObserver.observe(f));

  // Stat circle CSS conic-gradient
  document.querySelectorAll('.stat-circle').forEach(circle => {
    const pct = circle.dataset.pct;
    circle.style.setProperty('--pct', (pct / 100) * 360 + 'deg');
  });

  // Count up animation
  const countObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        const target = parseInt(el.dataset.target);
        const duration = 1500;
        const start = performance.now();
        function update(now) {
          const elapsed = now - start;
          const progress = Math.min(elapsed / duration, 1);
          el.textContent = Math.floor(progress * target);
          if (progress < 1) requestAnimationFrame(update);
          else el.textContent = target;
        }
        requestAnimationFrame(update);
        countObserver.unobserve(el);
      }
    });
  }, { threshold: 0.5 });
  document.querySelectorAll('.count-up').forEach(el => countObserver.observe(el));

  // Nav scroll effect
