<script>
  lucide.createIcons();

  function toggleDropdown(id) {
    const dd = document.getElementById(id);
    const wasOpen = dd.classList.contains('open');
    document.querySelectorAll('.nav-dropdown').forEach(d => d.classList.remove('open'));
    if (!wasOpen) dd.classList.add('open');
  }
  document.addEventListener('click', e => {
    if (!e.target.closest('.nav-dropdown')) document.querySelectorAll('.nav-dropdown').forEach(d => d.classList.remove('open'));
  });

  function toggleMobileMenu() { document.getElementById('mobileMenu').classList.toggle('active'); }
  function toggleMobileSub(id) {
    const el = document.getElementById(id);
    el.style.display = el.style.display === 'none' ? 'block' : 'none';
  }

  // Form validation
  const form = document.getElementById('demoForm');
  form.addEventListener('submit', function(e) {
    e.preventDefault();
    let valid = true;

    const fields = [
      { id: 'firstName', errorId: 'firstNameError', label: 'First name' },
      { id: 'lastName', errorId: 'lastNameError', label: 'Last name' },
      { id: 'company', errorId: 'companyError', label: 'Company' },
      { id: 'jobTitle', errorId: 'jobTitleError', label: 'Job title' },
      { id: 'country', errorId: 'countryError', label: 'Country' }
    ];

    fields.forEach(f => {
      const input = document.getElementById(f.id);
      const error = document.getElementById(f.errorId);
      if (!input.value.trim()) {
        input.classList.add('error');
        error.classList.add('visible');
        valid = false;
      } else {
        input.classList.remove('error');
        error.classList.remove('visible');
      }
    });

    // Email validation
    const email = document.getElementById('email');
    const emailError = document.getElementById('emailError');
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email.value.trim() || !emailRegex.test(email.value)) {
      email.classList.add('error');
      emailError.classList.add('visible');
      valid = false;
    } else {
      email.classList.remove('error');
      emailError.classList.remove('visible');
    }

    if (valid) {
      form.style.display = 'none';
      document.getElementById('successState').classList.add('visible');
    }
  });

  // Clear error on input
  document.querySelectorAll('.form-input').forEach(input => {
    input.addEventListener('input', () => {
      input.classList.remove('error');
      const errorEl = document.getElementById(input.id + 'Error');
      if (errorEl) errorEl.classList.remove('visible');
    });
    input.addEventListener('change', () => {
      input.classList.remove('error');
      const errorEl = document.getElementById(input.id + 'Error');
      if (errorEl) errorEl.classList.remove('visible');
    });
  });

  window.addEventListener('scroll', () => {
    document.getElementById('navbar').style.background = window.scrollY > 50 ? 'rgba(13,27,42,0.96)' : 'rgba(13,27,42,0.92)';
  });
</script>
